    output = [[1]*w for _ in range(h)]

    # Get all 3 positions
    threes = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 3]
    threes_by_row = {}
    for r,c in threes:
        if r not in threes_by_row:
            threes_by_row[r] = []
        threes_by_row[r].append(c)

    # Process row 13 (top, originally had 3s at [10-18, 20-21])
