        threes_top = threes_by_row[13]
        min_c, max_c = min(threes_top), max(threes_top)
        for c in range(min_c, max_c + 1):
            output[13][c] = 2

    # Process row 22 (bottom, preserve all 3s)
    if 22 in threes_by_row:
        threes_bottom = sorted(threes_by_row[22])
        for i, c in enumerate(threes_bottom[:-1]):
            for c2 in range(c+1, threes_bottom[i+1]):
                output[22][c2] = 2
        for c in threes_bottom:
            output[22][c] = 3

    # Process interior rows 14-21
    for r in range(14, 22):
        if r in threes_by_row:
            threes_row = sorted(threes_by_row[r])
            for i, c in enumerate(threes_row[:-1]):
                for c2 in range(c+1, threes_row[i+1]):
                    output[r][c2] = 2
            for c in threes_row:
                output[r][c] = 3

    return output

